    block_starts=[]
    for i in range(start_heading+1, len(lines)):
        s=lines[i].strip()
        if MARKER_RE.match(s):
            block_starts.append(i)
    if not block_starts:
        return None
    blocks=[]
    for idx, start in enumerate(block_starts):
        end=block_starts[idx+1] if idx+1 < len(block_starts) else len(lines)
        text=' '.join(l.strip() for l in lines[start:end] if l.strip())
        blocks.append((start,end,text))
    # collect until first report/cost block after at least one actual item.
