import json, pathlib, re
manifest=pathlib.Path('/mnt/data/LSF/results/nopv/agentic_rule_full_data_gpt54_adaptive/all_docs/q10_how_many_distinct_corrective_action_items_are_listed_in_the_.manifest.json')
obj=json.loads(manifest.read_text())
HEADING_RE = re.compile(r\"\\bPROPOSED\\s+COMPLIANCE\\s+ORDER\\b\", re.IGNORECASE)
REQUEST_RE = re.compile(r\"\\bit\\s+is\\s+requested(?:\\s*\\(not\\s+mandated\\))?\", re.IGNORECASE)
STOP_RE = re.compile(r\""'^(response'"\\s+to\\s+this\\s+notice|response\\s+options\\s+for\\s+pipeline\\s+operators|enclosures?:|sincerely|cc:|cc\\b)\", re.IGNORECASE)
PAGE_RE = re.compile(r\""'^(page'"\\s+\\d+(?:\\s+of\\s+\\d+)?)"'$", re.IGNORECASE)
LETTER_LABEL_RE = re.compile(r"''^'"\\s*([A-Z])(?:\\.(?"'![A-Z0-9]))?(?:'"\\s+|"'$)(.*)$")
NUMBER_LABEL_RE = re.compile(r"''^'"\\s*(\\d+)\\.(?"'!'"\\d)(?:\\s+|"'$)(.*)$")
ROMAN_RE = re.compile(r'"'"'^'"\\s*([ivxlcdm]+)\\.(?:\\s+|"'$)(.*)$'"', re.I)

def norm(text: str) -> str:
    return re.sub(r\"\\s+\", \" \", (text or \"\").replace('\\ufeff','').replace('\\x0c',' ')).strip()

def is_noise(text: str) -> bool:
    t=norm(text)
    return (not t) or bool(PAGE_RE.fullmatch(t)) or bool(re.fullmatch(r'\\d+', t))

def parse_numeric_path(text: str):
    m = re.match(r\""'^'"\\s*((?:\\d+)(?:\\.\\d+)*)(?:\\.(?"'!'"\\d))?(?:\\s+|"'$)", text)
    return m.group(1).split('"'.') if m else None

def parse_label(text: str):
    text = norm(text)
    m = LETTER_LABEL_RE.match(text)
    if m:
        return 'letter', [m.group(1)], m.group(2)
    path = parse_numeric_path(text)
    if path:
        rest = text[len('.'.join(path)):].lstrip('. ')
        return 'number', path, rest
    m=ROMAN_RE.match(text)
    if m:
        return 'roman', [m.group(1).lower()], m.group(2)
    return None, None, None

def looks_like_actual_order(lines, start_idx):
    nonnoise=[]
    for j in range(start_idx+1, min(len(lines), start_idx+10)):
        text=norm(lines[j])
        if is_noise(text):
            continue
        nonnoise.append(text)
        if len(nonnoise)>=4:
            break
    if not nonnoise: return False
    first=nonnoise[0].lower()
    if not first.startswith('pursuant'): return False
    joined=' '.join(nonnoise[:4]).lower()
    return 'proposes to issue' in joined and 'remedial requirements' in joined

def infer_top_level_scheme(lines, start_idx):
    for j in range(start_idx+1, min(len(lines), start_idx+80)):
        text=norm(lines[j])
        if not text or is_noise(text):
            continue
        if STOP_RE.match(text): return None
        if REQUEST_RE.search(text):
            continue
        m=LETTER_LABEL_RE.match(text)
        if m and len(m.group(1))==1:
            return 'letter'
        if NUMBER_LABEL_RE.match(text):
            return 'number'
    return None

def is_top_level_label(text, scheme):
    text=norm(text)
    if scheme=='letter':
        m=LETTER_LABEL_RE.match(text)
        return bool(m and len(m.group(1))==1)
    return bool(NUMBER_LABEL_RE.match(text))

def get_top_blocks(lines):
    heading_idxs=[i for i,t in enumerate(lines) if HEADING_RE.search(norm(t))]
    if not heading_idxs:
        return []
    chosen=None
    for idx in heading_idxs:
        if looks_like_actual_order(lines, idx):
            chosen=idx
            break
    if chosen is None:
        chosen=heading_idxs[-1]
    scheme=infer_top_level_scheme(lines, chosen)
    if scheme is None:
        return []
    top=[]
    i=chosen+1
    while i < len(lines):
        text=norm(lines[i])
        if not text or is_noise(text):
            i += 1
            continue
        if STOP_RE.match(text):
            break
        if is_top_level_label(text, scheme):
            top.append(i)
        i += 1
    blocks=[]
    for idx,start in enumerate(top):
        end=top[idx+1] if idx+1 < len(top) else len(lines)
        block=[norm(x) for x in lines[start:end] if norm(x) and not is_noise(x)]
        blocks.append(block)
    return blocks

def child_count(block):
    parent_kind,parent_path,_=parse_label(block[0])
    found=[]
    for s in block[1:]:
        kind,path,_=parse_label(s)
        if kind=='roman':
            if parent_kind=='letter':
                lab=path[0]
                if not found or found[-1]"'!=lab:
                    found.append(lab)
        elif kind=='"'number':
            if parent_kind=='number' and path and len(path)==len(parent_path)+1 and path[:len(parent_path)]==parent_path:
                lab='.'.join(path)
                if not found or found[-1]"'!=lab:
                    found.append(lab)
            elif parent_kind=='"'letter' and path and len(path)==1:
                lab=path[0]
                if not found or found[-1]"'!=lab:
                    found.append(lab)
    return len(found)

def block_descriptor(block):
    text='"' '.join(block)
    first_nonlabel=' '.join(block[1:3]) if len(block)>1 else block[0]
    return {
        'label': block[0],
        'request': bool(REQUEST_RE.search(text)),
        'kids': child_count(block),
        'colon': first_nonlabel.endswith(':') or block[0].endswith(':'),
        'intro_text': first_nonlabel,
    }

plus=[]
minus=[]
exact=0
for d in obj['documents']:
    lines=pathlib.Path(d['doc_path']).read_text(errors='ignore').splitlines()
    blocks=get_top_blocks(lines)
    top=len(blocks)
    if top==d['ground_truth']:
        exact += 1
    elif d['ground_truth']>top:
        plus.append((d['doc_name'], d['ground_truth'], top, [block_descriptor(b) for b in blocks]))
    else:
        minus.append((d['doc_name'], d['ground_truth'], top, [block_descriptor(b) for b in blocks]))
print('top exact', exact)
print('gt>top', len(plus), 'gt<top', len(minus))
print('\\nExamples gt>top')
for x in plus[:20]:
    print(x[0], 'gt',x[1],'top',x[2])
    for b in x[3]:
        print(' ', b)
    print()
PY"

