import json, pathlib, re
manifest=pathlib.Path('/mnt/data/LSF/results/nopv/agentic_rule_full_data_gpt54_adaptive/all_docs/q10_how_many_distinct_corrective_action_items_are_listed_in_the_.manifest.json')
obj=json.loads(manifest.read_text())
HEADING_RE = re.compile(r\""'^'"\\s*\\ufeff*\\f*PROPOSED\\s+COMPLIANCE\\s+ORDER\\s*"'$", re.IGNORECASE)
HEADING_ANY_RE = re.compile(r"'"\\bPROPOSED\\s+COMPLIANCE\\s+ORDER\\b\", re.IGNORECASE)
REQUEST_RE = re.compile(r\"\\bit\\s+is\\s+requested(?:\\s*\\(not\\s+mandated\\))?\", re.IGNORECASE)
STOP_RE = re.compile(r\""'^(response'"\\s+to\\s+this\\s+notice|response\\s+options\\s+for\\s+pipeline\\s+operators|enclosures?:|sincerely|cc:|cc\\b)\", re.IGNORECASE)
PAGE_RE = re.compile(r\""'^(page'"\\s+\\d+(?:\\s+of\\s+\\d+)?)"'$", re.IGNORECASE)
LETTER_LABEL_RE = re.compile(r"''^'"\\s*([A-Z])(?:\\.(?"'![A-Z0-9]))?(?:'"\\s+|"'$)(.*)$")
NUMBER_LABEL_RE = re.compile(r"''^'"\\s*(\\d+)\\.(?"'!'"\\d)(?:\\s+|"'$)(.*)$")


def norm(text: str) -> str:
    return re.sub(r"'"\\s+\", \" \", (text or \"\").replace('\\ufeff','').replace('\\x0c',' ')).strip()

def is_noise(text: str) -> bool:
    t=norm(text)
    return (not t) or bool(PAGE_RE.fullmatch(t)) or bool(re.fullmatch(r'\\d+', t))

def looks_like_actual_order(lines, start_idx):
    nonnoise=[]
    for j in range(start_idx+1, min(len(lines), start_idx+10)):
        text=norm(lines[j])
        if is_noise(text):
            continue
        nonnoise.append(text)
        if len(nonnoise)>=4:
            break
    if not nonnoise: return False
    joined=' '.join(nonnoise[:4]).lower()
    return nonnoise[0].lower().startswith('pursuant') and 'proposes to issue' in joined and 'remedial requirements' in joined

def infer_top_level_scheme(lines, start_idx):
    for j in range(start_idx+1, min(len(lines), start_idx+120)):
        text=norm(lines[j])
        if not text or is_noise(text):
            continue
        if STOP_RE.match(text): return None
        prev=norm(lines[j-1]) if j>0 else ''
        boundary=(not prev) or prev.endswith(':') or 'pipeline safety regulations:' in prev.lower()
        if not boundary:
            continue
        if REQUEST_RE.search(text):
            # request line can still indicate letter/number scheme if it has a label prefix
            pass
        if LETTER_LABEL_RE.match(text):
            return 'letter'
        if NUMBER_LABEL_RE.match(text):
            return 'number'
    return None

def is_top_level_label(lines, i, scheme):
    text=norm(lines[i])
    if not text or is_noise(text):
        return False
    prev=norm(lines[i-1]) if i>0 else ''
    boundary=(not prev) or prev.endswith(':') or 'pipeline safety regulations:' in prev.lower()
    if not boundary:
        return False
    if scheme=='letter':
        return bool(LETTER_LABEL_RE.match(text))
    return bool(NUMBER_LABEL_RE.match(text))

def get_top_blocks(lines):
    heading_idxs=[i for i,t in enumerate(lines) if HEADING_ANY_RE.search(norm(t))]
    if not heading_idxs:
        return []
    chosen=None
    for idx in heading_idxs:
        if looks_like_actual_order(lines, idx):
            chosen=idx
            break
    if chosen is None:
        chosen=heading_idxs[-1]
    scheme=infer_top_level_scheme(lines, chosen)
    if scheme is None:
        return []
    starts=[]
    for i in range(chosen+1, len(lines)):
        text=norm(lines[i])
        if text and STOP_RE.match(text):
            break
        if is_top_level_label(lines, i, scheme):
            starts.append(i)
    blocks=[]
    for idx,s in enumerate(starts):
        e=starts[idx+1] if idx+1 < len(starts) else len(lines)
        block=[norm(x) for x in lines[s:e] if norm(x) and not is_noise(x)]
        blocks.append(block)
    return blocks

exact=0
mism=[]
for d in obj['documents']:
    lines=pathlib.Path(d['doc_path']).read_text(errors='ignore').splitlines()
    c=len(get_top_blocks(lines))
    if c==d['ground_truth']:
        exact+=1
    else:
        mism.append((d['doc_name'], d['ground_truth'], c))
print('exact',exact,'of',len(obj['documents']))
print('mismatches',len(mism))
print(mism[:40])
PY"

